cd /workspace/graphic/js && cat >> template.js <<'EOF'

// ---- Porvoo notice: design-owned runtime (outside the generated region) ----

// Cross-fade the language stack to language n, FROM WHATEVER IS ON SCREEN NOW. Every language
// state (alternating or held) uses this as its dynamic, so a jump from any state - mid-fade,
// after a hold, on a recovery snap - lands on one clean pose with no flash of the other text.
function publicInfoCrossTo(n, opts) {
  var speed = (opts && opts.speed) || 1;
  var show = '.public-info-lang-' + n;
  var hide = '.public-info-lang-' + (n === 1 ? 2 : 1);
  var tagOn = '.public-info-tag-' + n;
  var tagOff = '.public-info-tag-' + (n === 1 ? 2 : 1);
  var tl = gsap.timeline();
  tl.to(hide, { opacity: 0, duration: 0.26 / speed, ease: 'sine.in' }, 0);
  tl.to(show, { opacity: 1, duration: 0.34 / speed, ease: 'sine.out' }, 0.24 / speed);
  tl.to(tagOff, { opacity: 0.5, duration: 0.3 / speed, ease: 'sine.inOut' }, 0.1 / speed);
  tl.to(tagOn, { opacity: 1, duration: 0.3 / speed, ease: 'sine.inOut' }, 0.1 / speed);
  return tl;
}
function publicInfoCrossTo1(target, opts) { return publicInfoCrossTo(1, opts); }
function publicInfoCrossTo2(target, opts) { return publicInfoCrossTo(2, opts); }

// The language names are set once (hidden word sources f5/f6) and painted into the tags.
function publicInfoPaintTags() {
  for (var n = 1; n <= 2; n++) {
    var src = document.getElementById('f' + (4 + n));
    var tag = document.querySelector('.public-info-tagword-' + n);
    if (src && tag) tag.textContent = src.textContent;
    var whole = document.querySelector('.public-info-tag-' + n);
    if (whole) whole.style.display = (src && /\S/.test(src.textContent || '')) ? '' : 'none';
  }
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', publicInfoPaintTags);
else publicInfoPaintTags();
EOF
